#include "tetris_priv.h"



//*****************************************************************************
// 6. APP CALLBACKS
//*****************************************************************************

// Begin a new game: reset state AND draw the playfield from scratch.
// (Called when the player picks Start on the title screen.)
static void StartGame(void)
{
    int16_t r, c;

    // Seed from the free-running timer so each game has a different order.
    Rand_Seed(TimerNow());

    for(r = 0; r < TETRIS_BOARD_H; r++)
        for(c = 0; c < TETRIS_BOARD_W; c++) tet_board[r][c] = 0;

    tet_score = 0;
    tet_lines = 0;
    tet_level = 0;
    tet_bagIdx = 7;                       // 7 = "deck empty", forces a shuffle
    tet_nextType = tet_NextFromBag();

    tet_frameNo       = 0;
    tet_hTimer        = 0;
    tet_prevMoveDir   = 0;
    tet_gameOver      = false;
    tet_gameOverTimer = 0;
    tet_gameOverDrawn = false;
    tet_gameOverRank  = -1;

    tet_clearing      = false;
    tet_clearMask     = 0;
    tet_clearTimer    = 0;
    tet_bannerKind    = BANNER_NONE;
    tet_bannerTimer   = 0;
    tet_bannerDirty   = false;
    tet_bannerErase   = false;
    tet_recordShown   = false;

    tet_DrawTetrisLayout();                 // also invalidates the screen cache
    tet_SpawnPiece();                       // an empty board always has room
    Buzzer_PlaySong(&song_tetris, 1);   // background music (stopped by the app loop on exit)
    // The first render() paints the board, preview and stats because the
    // cache was just invalidated.
}


// init: runs once at launch. Show the title screen; the game starts when the
// player picks Start.
static void Tetris_Init(void)
{
    tet_gameOverRank = -1;                // no gold highlight until a score is earned
    tet_hsLoaded     = false;             // never trust power-up RAM: reload the list from the save driver
    tet_nameActive   = false;
    tet_inTitle = true;
    tet_TitleInit();
}


// The stack reached the top. render() draws the overlay.
static void TetrisGameOver(void)
{
    tet_gameOver      = true;
    tet_gameOverTimer = TETRIS_GAME_OVER_HOLD_FRAMES;
    tet_clearing      = false;

    if(tet_bannerKind != BANNER_NONE)             // GAME OVER text replaces the banner
    {
        tet_bannerKind  = BANNER_NONE;
        tet_bannerTimer = 0;
        tet_bannerErase = true;
    }

    Buzzer_Stop();                              // silence on game over

    // Save the score (blank name) if it made the top 5. Blocks briefly
    // (flash). The name is typed afterwards.
    tet_gameOverRank = tet_HsSubmit(tet_score);
}


// update: once per frame. LOGIC ONLY. No drawing here.
static AppStatus Tetris_Update(void)
{
    uint16_t interval;
    bool     forceStep = false;
    int16_t  moveDir;                   // -1 left, 0 none, +1 right
    int16_t  moveEdge;                  // moveDir, but only on the frame it starts
    bool     softDrop;
    bool     rotate;

    // ---- Title screen: Start / High Scores ---------------------------------
    if(tet_inTitle)
    {
        TitleResult r = tet_TitleUpdate();

        if(r == TITLE_QUIT)  return APP_QUIT;       // back to the main menu
        if(r == TITLE_START) { tet_inTitle = false; StartGame(); }
        return APP_CONTINUE;
    }

    // ---- Game over: wait out the hold time, then any button ----------------
    //      top 5 -> name entry -> title;  otherwise -> title
    if(tet_gameOver)
    {
        if(tet_nameActive)
        {
            tet_NameUpdate();
        }
        else if(tet_gameOverTimer > 0)
        {
            tet_gameOverTimer--;
        }
        else if(g_joy.btnPressed || Dpad_AnyPressed())
        {
            if(tet_gameOverRank >= 0)
            {
                tet_NameBegin();            // top 5: ask for a name first
            }
            else
            {
                tet_inTitle = true;
                tet_TitleInit();
            }
        }

        return APP_CONTINUE;
    }

    // ---- Banner countdown (keeps running during the flash) -----------------
    if(tet_bannerTimer > 0 && --tet_bannerTimer == 0)
    {
        tet_bannerKind  = BANNER_NONE;
        tet_bannerErase = true;
    }

    // ---- Line-clear flash: the board is frozen until it ends ---------------
    if(tet_clearing)
    {
        if(--tet_clearTimer == 0 && !tet_FinishClear())
            TetrisGameOver();
        return APP_CONTINUE;
    }

    tet_frameNo++;

    // ---- 1. INPUT ----------------------------------------------------------
    // Merge stick and D-pad. If both D-pad sides are held they cancel out
    // and the stick decides.
    moveDir = g_joy.dirX;
    if(TETRIS_KEY_LEFT_HELD  && !TETRIS_KEY_RIGHT_HELD) moveDir = -1;
    if(TETRIS_KEY_RIGHT_HELD && !TETRIS_KEY_LEFT_HELD)  moveDir =  1;

    moveEdge      = (moveDir != 0 && moveDir != tet_prevMoveDir) ? moveDir : 0;
    tet_prevMoveDir = moveDir;

    softDrop = (g_joy.dirY > 0) || TETRIS_KEY_DOWN_HELD;
    rotate   = g_joy.btnPressed || TETRIS_KEY_ROTATE_TAP;

    // Left/right: move once immediately, then wait TETRIS_DAS_FRAMES before
    // repeating every TETRIS_ARR_FRAMES.
    if(moveDir == 0)
    {
        tet_hTimer = 0;
    }
    else if(moveEdge != 0)
    {
        tet_TetrisShift(moveDir);
        tet_hTimer = TETRIS_DAS_FRAMES;
    }
    else if(--tet_hTimer <= 0)
    {
        tet_TetrisShift(moveDir);
        tet_hTimer = TETRIS_ARR_FRAMES;
    }

    if(rotate) tet_TetrisRotate();                      // one rotation per tap

    if(softDrop && (tet_frameNo & 1)) forceStep = true;   // every other frame

    // ---- 2. GRAVITY --------------------------------------------------------
    interval = tet_gravityFrames[tet_level];
    tet_gravityCount++;

    if(forceStep || tet_gravityCount >= interval)
    {
        tet_gravityCount = 0;

        if(tet_Fits(tet_cur.type, tet_cur.rot, tet_cur.x, tet_cur.y + 1))
        {
            tet_cur.y++;                              // room below: fall one row
            if(softDrop) tet_score += 1;              // soft-drop bonus
        }
        else if(!tet_LockAndSpawn())
        {
            TetrisGameOver();
        }
    }

    // ---- 3. NEW #1: once per game, when the saved record is passed ---------
    // (Waits for a free banner, so it never cuts off a TETRIS! banner.)
    if(!tet_recordShown && tet_hs.score[0] > 0 && tet_score > tet_hs.score[0] && tet_bannerTimer == 0)
    {
        tet_recordShown = true;
        tet_ShowBanner(BANNER_RECORD);
        Buzzer_PlaySfx(&sfx_coin);              // swap for a fancier sfx from songs.h
    }

    return APP_CONTINUE;
}


// render: once per frame. DRAWING ONLY.
static void Tetris_Render(void)
{
    if(tet_inTitle)
    {
        tet_TitleRender();
        return;
    }

    if(tet_nameActive)
    {
        tet_NameRender();
        return;
    }

    if(tet_gameOverDrawn)
        return;                                     // nothing changes any more

    if(tet_bannerErase) tet_EraseBanner();                // must come BEFORE the board repaint

    tet_DrawTetrisBoard();                              // diff-based, cheap when idle
    tet_DrawBanner();                                   // only draws when new / painted over

    if(tet_gameOver)
    {
        tet_DrawGameOver();
        tet_gameOverDrawn = true;
    }
}



// redraw: called after the Settings overlay. Repaint only; keep game state.
static void Tetris_Redraw(void)
{
    if(tet_inTitle)
    {
        tet_TitleRedraw();           // title screen: just repaint it
        return;
    }

    if(tet_nameActive)
    {
        tet_nameDirtyFull  = true;        // name screen: just repaint it
        tet_nameDirtyBoxes = true;
        return;
    }

    tet_DrawTetrisLayout();                 // wipes LCD + invalidates s_shown / stats cache
    tet_gameOverDrawn = false;            // if the game was over, render() redraws the overlay
    tet_bannerDirty = (tet_bannerKind != BANNER_NONE);  // the wipe removed the banner box
    tet_bannerErase = false;
    if(!tet_gameOver)
        Buzzer_PlaySong(&song_tetris, 1);   // the runner stopped the music; restart it
}



